package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct {
	TrId     string
	TrIncome decimal.Decimal
}

var WsEofFlag string = "N"
var WsTax decimal.Decimal = decimal.Zero
var WsNet decimal.Decimal = decimal.Zero
var WsTotalTax decimal.Decimal = decimal.Zero
var WsCount int64 = 0
var WsIncEd string
var WsTaxEd string
var WsNetEd string
var WsTotalEd string

var taxRec TaxRec
var inputDone bool = false

var taxFileLines []string
var taxFileIdx int = 0

func isInputDone() bool {
	return inputDone
}

func fitDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	modulus := decimal.New(1, int32(intDigits)+scale)
	scaled := v.Shift(scale).Truncate(0)
	neg := scaled.IsNegative()
	abs := scaled
	if neg {
		abs = scaled.Neg()
	}
	m := abs.Mod(modulus)
	if neg {
		m = m.Neg()
	}
	return m.Shift(-scale)
}

func store9v99(v decimal.Decimal, intDigits int) decimal.Decimal {
	// caller already rounded/truncated to scale 2
	v = v.Truncate(2)
	return fitDecimal(v, intDigits, 2)
}

func formatEdited(val decimal.Decimal, picture string) string {
	// split picture
	dotPos := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotPos >= 0 {
		intPic = picture[:dotPos]
		fracPic = picture[dotPos+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	// placeholder types for integer part in order
	var ph []byte // 'Z' or '9'
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			ph = append(ph, c)
		}
	}
	nInt := len(ph)
	scale := len(fracPic)
	// scaled mod
	neg := val.IsNegative()
	abs := val
	if neg {
		abs = val.Neg()
	}
	scaled := abs.Shift(int32(scale)).Truncate(0)
	totalMod := decimal.New(1, int32(nInt+scale))
	scaledMod := scaled.Mod(totalMod)
	// int and frac
	divisor := decimal.New(1, int32(scale))
	intPartDec := scaledMod.Div(divisor).Truncate(0)
	fracPartDec := scaledMod.Mod(divisor)
	intPart := intPartDec.IntPart()
	fracPart := fracPartDec.IntPart()
	// digits
	digits := make([]byte, nInt)
	tmp := intPart
	for i := nInt - 1; i >= 0; i-- {
		digits[i] = byte(tmp % 10)
		tmp /= 10
	}
	// first non-zero
	firstNZ := -1
	for i := 0; i < nInt; i++ {
		if digits[i] != 0 {
			firstNZ = i
			break
		}
	}
	// suppressed flags per placeholder index
	suppressed := make([]bool, nInt)
	if firstNZ == -1 {
		for i := 0; i < nInt; i++ {
			if ph[i] == 'Z' {
				suppressed[i] = true
			} else {
				suppressed[i] = false
			}
		}
	} else {
		for i := 0; i < nInt; i++ {
			if i < firstNZ && ph[i] == 'Z' {
				suppressed[i] = true
			} else {
				suppressed[i] = false
			}
		}
	}
	// build int string
	var sb strings.Builder
	phIdx := 0
	// for comma decision: need to know if any unsuppressed digit to left
	// track
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			if suppressed[phIdx] {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte('0' + digits[phIdx])
			}
			phIdx++
		} else if c == ',' {
			// show comma only if there is an unsuppressed digit to the left
			// (i.e., any phIdx' < phIdx with !suppressed)
			show := false
			for k := 0; k < phIdx; k++ {
				if !suppressed[k] {
					show = true
					break
				}
			}
			if show {
				sb.WriteByte(',')
			} else {
				sb.WriteByte(' ')
			}
		} else {
			sb.WriteByte(c)
		}
	}
	intStr := sb.String()
	// frac string zero padded
	fracStr := fmt.Sprintf("%0*d", scale, fracPart)
	if dotPos >= 0 {
		return intStr + "." + fracStr
	}
	return intStr
}

func moveToEdited(val decimal.Decimal, picture string) string {
	return formatEdited(val, picture)
}

func formatCount9v3(v int64) string {
	m := v % 1000
	if m < 0 {
		m = -m
		// COBOL unsigned; just show absolute? keep positive
	}
	return fmt.Sprintf("%03d", m)
}

func parseIncomeField(s string) decimal.Decimal {
	if len(s) < 8 {
		s = s + strings.Repeat(" ", 8-len(s))
	}
	s = s[:8]
	// blanks => zero; replace spaces with 0 for parsing
	// if all spaces -> zero
	if strings.TrimSpace(s) == "" {
		return decimal.Zero
	}
	// remove spaces? treat as zero digits
	t := strings.ReplaceAll(s, " ", "0")
	t = strings.TrimSpace(t)
	// t should be digits
	var n int64 = 0
	for i := 0; i < len(t); i++ {
		c := t[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else {
			// non-digit: treat as 0
			n = n * 10
		}
	}
	return decimal.New(n, -2)
}

func parseLine(line string) TaxRec {
	// pad with spaces to 13
	if len(line) < 13 {
		line = line + strings.Repeat(" ", 13-len(line))
	}
	if len(line) > 13 {
		line = line[:13]
	}
	id := line[0:5]
	inc := parseIncomeField(line[5:13])
	return TaxRec{TrId: id, TrIncome: inc}
}

func READPARA() {
	if taxFileIdx >= len(taxFileLines) {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	line := taxFileLines[taxFileIdx]
	taxFileIdx++
	taxRec = parseLine(line)
}

func PROCESSPARA() {
	trIncome := taxRec.TrIncome
	limit10000 := decimal.New(1000000, -2)
	limit40000 := decimal.New(4000000, -2)
	rate10 := decimal.New(10, -2)
	rate20 := decimal.New(20, -2)
	rate30 := decimal.New(30, -2)
	c1000 := decimal.New(100000, -2)
	c7000 := decimal.New(700000, -2)
	c10000 := decimal.New(1000000, -2)
	c40000 := decimal.New(4000000, -2)
	var tax decimal.Decimal
	if trIncome.Cmp(limit10000) <= 0 {
		tax = trIncome.Mul(rate10).Round(2)
	} else {
		if trIncome.Cmp(limit40000) <= 0 {
			tax = c1000.Add(trIncome.Sub(c10000).Mul(rate20)).Round(2)
		} else {
			tax = c7000.Add(trIncome.Sub(c40000).Mul(rate30)).Round(2)
		}
	}
	WsTax = store9v99(tax, 7)
	netRaw := trIncome.Sub(WsTax).Truncate(2)
	WsNet = store9v99(netRaw, 7)
	WsTotalTax = store9v99(WsTotalTax.Add(WsTax).Truncate(2), 9)
	WsCount = (WsCount + 1) % 1000
	WsIncEd = moveToEdited(trIncome, "ZZZ,ZZ9.99")
	WsTaxEd = moveToEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = moveToEdited(WsNet, "ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s\n", taxRec.TrId, WsIncEd, WsTaxEd, WsNetEd)
	READPARA()
}

func MAINPARA() {
	// OPEN INPUT TAX-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty?
		fmt.Fprintf(os.Stderr, "open error: %v\n", err)
		os.Exit(1)
	}
	scanner := bufio.NewScanner(f)
	// allow long lines; default is fine (13 bytes)
	// preserve trailing spaces? Scanner strips \r\n but keeps other spaces except trailing \r?
	// Note: bufio.Scanner will keep trailing spaces. Good.
	taxFileLines = nil
	for scanner.Scan() {
		// scanner.Text() strips \r\n (and \r). Use as is.
		line := scanner.Text()
		taxFileLines = append(taxFileLines, line)
	}
	f.Close()
	taxFileIdx = 0
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE TAX-FILE (already closed)
	WsTotalEd = moveToEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	countStr := formatCount9v3(WsCount)
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", countStr, WsTotalEd)
}

func main() {
	MAINPARA()
}
